/**
 * 依據知識點物件取得其專屬的 SVG Infographic 資訊圖卡
 * 1. 優先匹配專屬微知識點 Infographic (specializedKnowledgeInfographics)
 * 2. 其次匹配該單元之精準高畫質向量架構圖 (unitDiagramCatalog)
 * 3. 最後提供自適應高畫質核心微概念卡 (generic fallback)
 */
export function getKnowledgePointInfographic(knowledgePoint) {
  if (!knowledgePoint) {
    return {
      title: '108 課綱核心圖解',
      subtitle: '概念視覺化架構',
      diagramType: 'default',
      svg: `<svg viewBox="0 0 240 140" width="100%" height="100%"><rect width="240" height="140" fill="#f8fafc" rx="8" /><text x="120" y="75" text-anchor="middle" fill="#64748b" font-size="13">108 課綱視覺化圖解</text></svg>`
    };
  }

  // 1. 優先檢查專屬微知識點 Infographic
  if (specializedKnowledgeInfographics[knowledgePoint.id]) {
    return specializedKnowledgeInfographics[knowledgePoint.id];
  }

  // 2. 檢查單元級向量圖示引擎 (unitDiagramCatalog)
  const unitDiagram = unitDiagramCatalog[knowledgePoint.unitId];
  if (unitDiagram && unitDiagram.svg) {
    return {
      title: `${knowledgePoint.title}・單元核心圖解`,
      subtitle: unitDiagram.subtitle || `${knowledgePoint.category} 考點精要`,
      diagramType: 'unit-diagram',
      svg: unitDiagram.svg
    };
  }

  // 3. 通用高畫質純向量 SVG 資訊圖表卡
  return {
    title: knowledgePoint.title,
    subtitle: `${knowledgePoint.category}・核心微概念圖解`,
    diagramType: 'generic',
    svg: `<svg viewBox="0 0 320 180" width="100%" height="100%" xmlns="http://www.w3.org/2000/svg">
      <rect width="320" height="180" fill="#f8fafc" rx="10" stroke="#e2e8f0" stroke-width="1.5" />
      <rect x="20" y="16" width="280" height="32" rx="6" fill="#3b82f6" />
      <text x="160" y="37" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">${knowledgePoint.title}</text>
      
      <rect x="25" y="58" width="270" height="42" rx="5" fill="#eff6ff" stroke="#93c5fd" />
      <text x="35" y="76" font-size="10" font-weight="bold" fill="#1e40af">【核心定律與推導】</text>
      <text x="35" y="92" font-size="9" fill="#1e3a8a">${(knowledgePoint.formulaOrRule || '掌握基本定義與解題步驟').slice(0, 48)}</text>
      
      <rect x="25" y="108" width="130" height="42" rx="4" fill="#ecfdf5" stroke="#10b981" />
      <text x="90" y="124" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#047857">生活素養實用性</text>
      <text x="90" y="139" text-anchor="middle" font-size="8" fill="#065f46">真實情境問題解決</text>

      <rect x="165" y="108" width="130" height="42" rx="4" fill="#fee2e2" stroke="#ef4444" />
      <text x="230" y="124" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#991b1b">段考防雷針</text>
      <text x="230" y="139" text-anchor="middle" font-size="8" fill="#7f1d1d">圈出關鍵字避免粗心</text>

      <text x="160" y="166" text-anchor="middle" font-size="9" font-weight="bold" fill="#64748b">108 課綱六年級素養微概念・國中七年級先修橋樑</text>
    </svg>`
  };
}
